import firebase from 'firebase/app';
import 'firebase/database'; // Import the Firebase Realtime Database module

const firebaseConfig = {
    apiKey: "AIzaSyADmXqIuQyG0nZ4Yeu7Hi13m2EP7oX6PfU",
    authDomain: "akecommerce-app.firebaseapp.com",
    databaseURL: "https://akecommerce-app-default-rtdb.firebaseio.com",
    projectId: "akecommerce-app",
    storageBucket: "akecommerce-app.appspot.com",
    messagingSenderId: "76579350076",
    appId: "1:76579350076:web:abcdef1234567890"
};

// Initialize Firebase
const app = firebase.initializeApp(firebaseConfig);

export const db = app.database(); // Export the Firebase database instance
